/* Dinosaurs set additions — cards appended after dinosaurs.js.
   (dinosaurs.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'dinosaurs.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('dinosaurs');
  if (!S) return;
  var extra = [{"name":"Triceratops","rarity":"chase","id":"triceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous giant from Montana and Wyoming, Triceratops bore three horns and a solid bony frill, and was among the last dinosaurs before the asteroid.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Triceratops_TD.png"},{"name":"Styracosaurus","rarity":"legendary","id":"styracosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Styracosaurus combined a single long nose horn with a crown of spikes around the edge of its frill.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a7/Styracosaurus_TD.png"},{"name":"Pachyrhinosaurus","rarity":"legendary","id":"pachyrhinosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Canada and Alaska, Pachyrhinosaurus replaced the nose horn with a thick, flattened pad of roughened bone.","image":"https://upload.wikimedia.org/wikipedia/commons/2/26/Pachyrhinosaurus_TD.png"},{"name":"Kosmoceratops","rarity":"legendary","id":"kosmoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Utah, Kosmoceratops had forward-hooking frill horns that make its skull among the most ornate of any ceratopsian.","image":"https://upload.wikimedia.org/wikipedia/commons/8/81/Kosmoceratops_NT_small_%282%29_transparent.png"},{"name":"Centrosaurus","rarity":"epic","id":"centrosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Centrosaurus carried one huge curved nose horn and is known from massive single-species bonebeds.","image":"https://upload.wikimedia.org/wikipedia/commons/4/49/Centrosaurus.png"},{"name":"Pentaceratops","rarity":"epic","id":"pentaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from New Mexico, Pentaceratops bore a very large, elongated frill on one of the biggest skulls in its group.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Pentaceratops_BW_flipped_transparent.png"},{"name":"Chasmosaurus","rarity":"epic","id":"chasmosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Chasmosaurus had a long, open frill with large holes and a distinctive heart-shaped outline.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f5/Chasmosaurus_BW_transparent.png"},{"name":"Protoceratops","rarity":"epic","id":"protoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur relative from Mongolia, Protoceratops was small and hornless, and is famous from nests, eggs and desert bonebeds.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Protoceratops_TD.png"},{"name":"Psittacosaurus","rarity":"epic","id":"psittacosaurus","subtitle":"Ceratopsian","details":"An Early Cretaceous early ceratopsian from Asia, Psittacosaurus had a parrot-like beak and tail bristles, and is known from hundreds of specimens.","image":"https://upload.wikimedia.org/wikipedia/commons/1/15/Psittacosaurus_TD.png"},{"name":"Diabloceratops","rarity":"rare","id":"diabloceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Utah, Diabloceratops was an early centrosaur bearing two striking pairs of horns around its frill.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Diabloceratops_TD.png"},{"name":"Nasutoceratops","rarity":"rare","id":"nasutoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Montana, Nasutoceratops was a big-nosed ceratopsian with long, bull-like brow horns curving forward.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f3/Nasutoceratops_TD.png"},{"name":"Regaliceratops","rarity":"rare","id":"regaliceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Regaliceratops wore a crown-like frill rimmed with triangular plates, earning it the nickname Hellboy.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Regaliceratops_peterhewsi_abelov.jpg"},{"name":"Einiosaurus","rarity":"rare","id":"einiosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Montana, Einiosaurus had a nose horn that curves sharply forward, like the blade of a bottle opener.","image":"https://upload.wikimedia.org/wikipedia/commons/2/27/Einiosaurus_procurvicornis.png"},{"name":"Achelousaurus","rarity":"rare","id":"achelousaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Montana, Achelousaurus carried rough, knobbly bony bosses in place of sharp horns on its nose and brow.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e0/Achelousaurus_horneri.png"},{"name":"Medusaceratops","rarity":"rare","id":"medusaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Medusaceratops bore large frill hooks curling downward and was once misidentified as Chasmosaurus.","image":"https://upload.wikimedia.org/wikipedia/commons/b/be/Medusaceratops_TD.png"},{"name":"Sinoceratops","rarity":"rare","id":"sinoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from China, Sinoceratops was a large centrosaur with a frill of forward-curving hornlets, a rarity in Asia.","image":"https://upload.wikimedia.org/wikipedia/commons/b/be/Sinoceratops_zhuchengensis.png"},{"name":"Titanoceratops","rarity":"rare","id":"titanoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous giant from New Mexico, Titanoceratops was a long-horned ceratopsian that rivalled Triceratops in overall size and skull length.","image":"https://upload.wikimedia.org/wikipedia/commons/5/52/Titanoceratops_ouranos_life_restoration.jpg"},{"name":"Albertaceratops","rarity":"uncommon","id":"albertaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta and Montana, Albertaceratops was an early centrosaur carrying unusually long brow horns for its group.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/Albertaceratops_TD.png"},{"name":"Anchiceratops","rarity":"uncommon","id":"anchiceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Anchiceratops had a long frill, a thick hooked beak and horns, and lived near ancient coastal plains.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Anchiceratops_dinosaur.png"},{"name":"Arrhinoceratops","rarity":"uncommon","id":"arrhinoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Arrhinoceratops was named no-nose-horn face after its tiny nose horn was initially overlooked.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3f/Arrhinoceratops_TD.png"},{"name":"Avaceratops","rarity":"uncommon","id":"avaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Montana, Avaceratops was a relatively small ceratopsian known mainly from a single juvenile skeleton.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1e/Avaceratops_BW.jpg"},{"name":"Bravoceratops","rarity":"uncommon","id":"bravoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Texas, Bravoceratops was a large chasmosaur from Big Bend with a narrow frill tipped by a small bar of bone.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e9/Bravoceratops_NT_small.jpg"},{"name":"Coahuilaceratops","rarity":"uncommon","id":"coahuilaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Mexico, Coahuilaceratops was among the first ceratopsians named there, with huge, strongly curved brow horns.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/Coahuilaceratops_NT.jpg"},{"name":"Coronosaurus","rarity":"uncommon","id":"coronosaurus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Coronosaurus carried clusters of small hornlets around the top of its frill, like a bony crown.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Coronosaurus_NT_small.jpg"},{"name":"Spiclypeus","rarity":"uncommon","id":"spiclypeus","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Montana, Spiclypeus was a chasmosaur whose brow horns and frill spikes pointed in several directions at once.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cb/Spiclypeus_NT_small.jpg"},{"name":"Wendiceratops","rarity":"uncommon","id":"wendiceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Wendiceratops was an early centrosaur with a hooked, forward-curling edge along its frill.","image":"https://dinodata.de/images/dinosaurs/dino_w/%7Ewendiceratops/wendiceratops_by_tuomaskoivurinne.webp"},{"name":"Xenoceratops","rarity":"uncommon","id":"xenoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Alberta, Xenoceratops was one of the oldest large centrosaurs known from Canada, with a spiked frill.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8f/Xenoceratops_NT_small.jpg"},{"name":"Zuniceratops","rarity":"uncommon","id":"zuniceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from New Mexico, Zuniceratops was the earliest known North American ceratopsian with true horns over its eyes.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/Zuniceratops_BW.jpg"},{"name":"Agujaceratops","rarity":"uncommon","id":"agujaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous horned dinosaur from Texas, Agujaceratops was a chasmosaur with a deeply notched frill, once lumped together with Chasmosaurus.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Agujaceratops_life_restoration.jpg"},{"name":"Leptoceratops","rarity":"common","id":"leptoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small hornless ceratopsian from Montana and Wyoming, Leptoceratops retained a beak and frill but walked and ran mainly on two legs.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Leptoceratops_BW.jpg"},{"name":"Montanoceratops","rarity":"common","id":"montanoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Montana, Montanoceratops was a leptoceratopsid with an unusually tall row of spines along its tail.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Montanoceratops_BW.jpg"},{"name":"Bagaceratops","rarity":"common","id":"bagaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Mongolia, Bagaceratops was a protoceratopsid with a tiny horn-like bump on its snout and a deep beak.","image":"https://upload.wikimedia.org/wikipedia/commons/0/09/Bagaceratops_Restoration.png"},{"name":"Udanoceratops","rarity":"common","id":"udanoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous ceratopsian from Mongolia, Udanoceratops was the largest known leptoceratopsid, armed with a deep, powerful beak for cropping plants.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2a/Udanoceratops_Restoration.png"},{"name":"Liaoceratops","rarity":"common","id":"liaoceratops","subtitle":"Ceratopsian","details":"An Early Cretaceous tiny ceratopsian from China, Liaoceratops hints at the small, two-legged beginnings of the lineage that later produced Triceratops.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/Liaoceratops_BW.jpg"},{"name":"Auroraceratops","rarity":"common","id":"auroraceratops","subtitle":"Ceratopsian","details":"An Early Cretaceous small frilled ceratopsian from China, Auroraceratops is known from many well-preserved skeletons of this early horned dinosaur.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Auroraceratops_TD.png"},{"name":"Archaeoceratops","rarity":"common","id":"archaeoceratops","subtitle":"Ceratopsian","details":"An Early Cretaceous early ceratopsian from China, Archaeoceratops walked on two legs and showed only a hint of the frill its later relatives enlarged.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b8/Archaeoceratops_NT.jpg"},{"name":"Yamaceratops","rarity":"common","id":"yamaceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Mongolia, Yamaceratops bridges the early two-legged forms and the later, larger frilled horned dinosaurs.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8e/Yamaceratops_BW.jpg"},{"name":"Graciliceratops","rarity":"common","id":"graciliceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Mongolia, Graciliceratops was a lightly built protoceratopsid known from a single partial skeleton.","image":"https://upload.wikimedia.org/wikipedia/commons/2/22/Graciliceratops_BW.jpg"},{"name":"Breviceratops","rarity":"common","id":"breviceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Mongolia, Breviceratops was a protoceratopsid whose adults still retained teeth in the upper jaw.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Breviceratops_Restoration.png"},{"name":"Cerasinops","rarity":"common","id":"cerasinops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Montana, Cerasinops was a leptoceratopsid distinguished by a distinctive hooked bone in its cheek.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Cerasinops_BW.jpg"},{"name":"Prenoceratops","rarity":"common","id":"prenoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Montana, Prenoceratops is known from a bonebed preserving several young individuals buried together.","image":"https://upload.wikimedia.org/wikipedia/commons/d/da/Prenoceratops_BW.jpg"},{"name":"Gryphoceratops","rarity":"common","id":"gryphoceratops","subtitle":"Ceratopsian","details":"An early Late Cretaceous tiny ceratopsian from Alberta, Gryphoceratops is a small leptoceratopsid known only from a single lower jawbone.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Gryphoceratops_morrisoni.png"},{"name":"Unescoceratops","rarity":"common","id":"unescoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous small ceratopsian from Alberta, Unescoceratops was a leptoceratopsid recognised by its distinctive axe-shaped lower jaw.","image":"https://scx2.b-cdn.net/gfx/news/hires/2012/1-scientistsna.jpg"},{"name":"Koreaceratops","rarity":"common","id":"koreaceratops","subtitle":"Ceratopsian","details":"An Early Cretaceous ceratopsian from South Korea, Koreaceratops was the first of its group named from Korea, with a deep, paddle-like tail.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Koreaceratops_NT.jpg"},{"name":"Turanoceratops","rarity":"common","id":"turanoceratops","subtitle":"Ceratopsian","details":"A Late Cretaceous ceratopsian from Uzbekistan, Turanoceratops was a transitional form close to the line leading to the great horned ceratopsids.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bd/Turanoceratops_tardabilis_life_restoration.jpg"},{"name":"Stegosaurus","rarity":"chase","id":"stegosaurus","subtitle":"Armored","details":"A Late Jurassic plated dinosaur from Colorado and Wyoming, Stegosaurus bore twin rows of back plates and a tail armed with four long spikes.","image":"https://upload.wikimedia.org/wikipedia/commons/0/09/Stegosaurus_TD.png"},{"name":"Ankylosaurus","rarity":"chase","id":"ankylosaurus","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Montana, Ankylosaurus was a heavily plated tank of a herbivore ending in a massive bony tail club.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Ankylosaurus_TD.png"},{"name":"Euoplocephalus","rarity":"legendary","id":"euoplocephalus","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Alberta, Euoplocephalus was among the best-known ankylosaurs, with armour even over its eyelids.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ec/Euoplocephalus_TD.png"},{"name":"Borealopelta","rarity":"legendary","id":"borealopelta","subtitle":"Armored","details":"An Early Cretaceous armoured dinosaur from Alberta, Borealopelta was an exceptionally preserved nodosaur, complete with armour and skin in place.","image":"https://upload.wikimedia.org/wikipedia/commons/3/36/Borealopelta_TD.png"},{"name":"Kentrosaurus","rarity":"legendary","id":"kentrosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from Tanzania, Kentrosaurus mixed plates along its neck and back with long spikes over its shoulders, hips and tail.","image":"https://upload.wikimedia.org/wikipedia/commons/6/63/Kentrosaurus_TD.png"},{"name":"Edmontonia","rarity":"epic","id":"edmontonia","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Alberta and Alaska, Edmontonia was a nodosaur with long shoulder spikes and no club on its tail.","image":"https://upload.wikimedia.org/wikipedia/commons/9/93/Edmontonia_TD.png"},{"name":"Pinacosaurus","rarity":"epic","id":"pinacosaurus","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Mongolia, Pinacosaurus was a desert ankylosaur known from many juveniles found preserved together.","image":"https://upload.wikimedia.org/wikipedia/commons/1/15/Life_reconstruction_of_Pinacosaurus_grangeri.png"},{"name":"Saichania","rarity":"epic","id":"saichania","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Mongolia, Saichania was a ruggedly armoured ankylosaur with a tail club, built for life in the Gobi Desert.","image":"https://dinodata.de/images/dinosaurs/dino_s/%7Esaichania/Saichania-by_Olorotitan.webp"},{"name":"Tarchia","rarity":"epic","id":"tarchia","subtitle":"Armored","details":"A Late Cretaceous armoured dinosaur from Mongolia, Tarchia was a large ankylosaur whose name means brainy, a nod to its comparatively roomy skull.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7f/Tarchia_TD.png"},{"name":"Huayangosaurus","rarity":"epic","id":"huayangosaurus","subtitle":"Armored","details":"A Middle Jurassic stegosaur from China, Huayangosaurus was one of the oldest and most primitive true stegosaurs, with plates, spikes and a spiked tail.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e1/Huayangosaurus_TD.png"},{"name":"Polacanthus","rarity":"epic","id":"polacanthus","subtitle":"Armored","details":"An Early Cretaceous nodosaur from England, Polacanthus carried a fused shield of solid armor over its hips, backed by rows of spikes and bony plates.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Polacanthus_TD.png"},{"name":"Gastonia","rarity":"rare","id":"gastonia","subtitle":"Armored","details":"An Early Cretaceous nodosaur from Utah, Gastonia was covered in blade-like spikes along its sides, with a spiny tail and armor protecting its back.","image":"https://upload.wikimedia.org/wikipedia/commons/5/55/Gastonia_TD.png"},{"name":"Sauropelta","rarity":"rare","id":"sauropelta","subtitle":"Armored","details":"An Early Cretaceous nodosaur from Wyoming and Montana, Sauropelta had a heavily armored neck ringed by large spikes and a body covered in bony plates.","image":"https://upload.wikimedia.org/wikipedia/commons/8/85/Emily_Willoughby%27s_Sauropelta_reconstruction_Rotated.png"},{"name":"Panoplosaurus","rarity":"rare","id":"panoplosaurus","subtitle":"Armored","details":"A Late Cretaceous nodosaur from Alberta, Panoplosaurus was covered in rounded armored studs and is among the last nodosaurs known from the fossil record.","image":"https://dinodata.de/images/dinosaurs/dino_p/%7Epanoplosaurus/journal.pone.0067182.g006_CC.webp"},{"name":"Zuul","rarity":"rare","id":"zuul","subtitle":"Armored","details":"A Late Cretaceous club-tailed ankylosaur from Montana, Zuul was named for the Ghostbusters gatekeeper and defended itself with spikes and a heavy tail club.","image":"https://upload.wikimedia.org/wikipedia/commons/8/85/Zuul_TD.png"},{"name":"Tuojiangosaurus","rarity":"rare","id":"tuojiangosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from China, Tuojiangosaurus carried plates down its back and paired spikes running all the way to the tip of its muscular tail.","image":"https://upload.wikimedia.org/wikipedia/commons/3/30/Tuojiangosaurus_multispinus_life_restoration.jpg"},{"name":"Wuerhosaurus","rarity":"rare","id":"wuerhosaurus","subtitle":"Armored","details":"An Early Cretaceous stegosaur from China, Wuerhosaurus was a late survivor of its group, with low, broad plates along its back and spikes on its tail.","image":"https://upload.wikimedia.org/wikipedia/commons/5/55/Wuerhosaurus_homheni.png"},{"name":"Miragaia","rarity":"rare","id":"miragaia","subtitle":"Armored","details":"A Late Jurassic stegosaur from Portugal, Miragaia had an unusually long neck built from seventeen vertebrae, far more than most other stegosaurs had.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Miragaia_longicollum.png"},{"name":"Hesperosaurus","rarity":"rare","id":"hesperosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from Wyoming, Hesperosaurus carried broad plates in a distinctive single row along its back and spikes at the end of its tail.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Hesperosaurus_mjosi.png"},{"name":"Dacentrurus","rarity":"rare","id":"dacentrurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from England, Dacentrurus was the first stegosaur ever described, mixing small back plates with paired spikes along its tail.","image":"https://upload.wikimedia.org/wikipedia/commons/4/47/Dacentrurus_TD.png"},{"name":"Hylaeosaurus","rarity":"uncommon","id":"hylaeosaurus","subtitle":"Armored","details":"An Early Cretaceous armored dinosaur from England, Hylaeosaurus was one of the three original dinosaurs named in the 1840s, with spines along its back.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Hylaeosaurus_TD.png"},{"name":"Minmi","rarity":"uncommon","id":"minmi","subtitle":"Armored","details":"An Early Cretaceous ankylosaur from Australia, Minmi was small for its group and unusually carried bony plates protecting even the underside of its belly.","image":"https://dinodata.de/images/dinosaurs/dino_m/%7Eminmi/minmi-brian_choo.webp"},{"name":"Cedarpelta","rarity":"uncommon","id":"cedarpelta","subtitle":"Armored","details":"An Early Cretaceous nodosaur from Utah, Cedarpelta was a large, primitive member of its family, known mainly from well-preserved skulls and armored remains.","image":"https://dinodata.de/images/dinosaurs/dino_c/%7Ecedarpelta/Cedarpelta_atuchin.webp"},{"name":"Animantarx","rarity":"uncommon","id":"animantarx","subtitle":"Armored","details":"A Late Cretaceous nodosaur from Utah, Animantarx was named for the radioactive rock layers around its fossils, which helped reveal its buried skeleton.","image":"https://upload.wikimedia.org/wikipedia/commons/2/28/Animantarx_ramaljonesi.png"},{"name":"Europelta","rarity":"uncommon","id":"europelta","subtitle":"Armored","details":"An Early Cretaceous nodosaur from Spain, Europelta is the earliest nodosaur known from Europe, discovered in a region long worked for coal mining.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Europelta.jpg"},{"name":"Hungarosaurus","rarity":"uncommon","id":"hungarosaurus","subtitle":"Armored","details":"A Late Cretaceous ankylosaur from Hungary, Hungarosaurus is the most complete ankylosaur found in Europe, known from several partial skeletons.","image":"https://images.dinosaurpictures.org/hungarosaurus_by_hyrotrioskjan-d3l3xgx_a02a.jpg"},{"name":"Stegouros","rarity":"uncommon","id":"stegouros","subtitle":"Armored","details":"A Late Cretaceous armored parankylosaur from Chile, Stegouros was small, with a tail ending in a flat weapon of fused bony blades like a macuahuitl.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Stegouros_TD.png"},{"name":"Jakapil","rarity":"uncommon","id":"jakapil","subtitle":"Armored","details":"A Late Cretaceous armored dinosaur from Argentina, Jakapil was a small bipedal thyreophoran and an early-diverging member of the ankylosaur family tree.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Jakapil_TD.png"},{"name":"Struthiosaurus","rarity":"uncommon","id":"struthiosaurus","subtitle":"Armored","details":"A Late Cretaceous nodosaur from Austria and Romania, Struthiosaurus was a small island dweller of ancient Europe, protected by spikes and bony armor.","image":"https://upload.wikimedia.org/wikipedia/commons/0/01/1871_-_Struthiosaurus.png"},{"name":"Chungkingosaurus","rarity":"uncommon","id":"chungkingosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from China, Chungkingosaurus was smaller than many relatives, with plates on its back and tail spikes that pointed in pairs.","image":"https://upload.wikimedia.org/wikipedia/commons/7/73/Chungkingosaurus_jiangbeiensis.png"},{"name":"Gigantspinosaurus","rarity":"uncommon","id":"gigantspinosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from China, Gigantspinosaurus is named for the enormous curved spines that rose over its shoulders and towered above its back.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Gigantspinosaurus_sichuanensis.png"},{"name":"Aletopelta","rarity":"uncommon","id":"aletopelta","subtitle":"Armored","details":"A Late Cretaceous nodosaur from California, Aletopelta was first found off the southern California coast, its armored remains washed out to sea long ago.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c4/Aletopelta_TD.png"},{"name":"Pawpawsaurus","rarity":"uncommon","id":"pawpawsaurus","subtitle":"Armored","details":"An Early Cretaceous nodosaur from Texas, Pawpawsaurus had bony eyelids and a well-preserved skull that revealed unusual details of nodosaur head anatomy.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d9/Pawpawsaurus_reconstuction.png"},{"name":"Adratiklit","rarity":"common","id":"adratiklit","subtitle":"Armored","details":"A Late Jurassic stegosaur from Morocco, Adratiklit comes from the first Jurassic dinosaur sites found in the Atlas Mountains of North Africa.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d3/Adratiklit_boulahfa.png"},{"name":"Bashanosaurus","rarity":"common","id":"bashanosaurus","subtitle":"Armored","details":"A Middle Jurassic stegosaur from China, Bashanosaurus was small and early, ranking among the oldest stegosaurs known from Asia in the fossil record.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Bashanosaurus_primitivus.png"},{"name":"Loricatosaurus","rarity":"common","id":"loricatosaurus","subtitle":"Armored","details":"A Late Jurassic stegosaur from England and France, Loricatosaurus was long confused with Lexovisaurus material before being recognized as its own genus.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Loricatosaurus_priscus.png"},{"name":"Mongolostegus","rarity":"common","id":"mongolostegus","subtitle":"Armored","details":"An Early Cretaceous stegosaur from Mongolia, Mongolostegus was a late survivor of its group, known mainly from tail vertebrae and pieces of its armor.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ef/Mongolostegus_exspectabilis.png"},{"name":"Paranthodon","rarity":"common","id":"paranthodon","subtitle":"Armored","details":"An Early Cretaceous stegosaur from South Africa, Paranthodon is one of the few stegosaurs known from Africa, recognized from partial skull and teeth fossils.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Paranthodon_africanus.png"},{"name":"Akainacephalus","rarity":"common","id":"akainacephalus","subtitle":"Armored","details":"A Late Cretaceous ankylosaur from Utah, Akainacephalus had a spiky, heavily ornamented head and came from the rich Kaiparowits badlands fossil beds.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Akainacephalus_%28updated%29.png"},{"name":"Crichtonsaurus","rarity":"common","id":"crichtonsaurus","subtitle":"Armored","details":"A Late Cretaceous ankylosaur from China, Crichtonsaurus was a small armored herbivore named for Michael Crichton, author of the novel Jurassic Park.","image":"https://dinodata.de/images/dinosaurs/dino_c/%7Ecrichtonsaurus/Crichtonsaurus-by-Raul-Lunia.webp"},{"name":"Dyoplosaurus","rarity":"common","id":"dyoplosaurus","subtitle":"Armored","details":"A Late Cretaceous club-tailed ankylosaur from Alberta, Dyoplosaurus was rediscovered after decades spent classified as a species of Euoplocephalus.","image":"https://images.dinosaurpictures.org/Dyoplosaurus/Dyoplosaurus_990b8680.jpg"},{"name":"Gobisaurus","rarity":"common","id":"gobisaurus","subtitle":"Armored","details":"An Early Cretaceous ankylosaur from China, Gobisaurus was a large basal member of its family, known from a complete skull found in the Gobi region.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/GobisaurusNV_transparent.png"},{"name":"Liaoningosaurus","rarity":"common","id":"liaoningosaurus","subtitle":"Armored","details":"An Early Cretaceous ankylosaur from China, Liaoningosaurus was unusually small, and its anatomy has raised debated ideas about a partly aquatic life.","image":"https://i.pinimg.com/736x/3b/70/da/3b70dafce31a51a45e55a697d83d69f6.jpg"},{"name":"Mymoorapelta","rarity":"common","id":"mymoorapelta","subtitle":"Armored","details":"A Late Jurassic armored dinosaur from Colorado, Mymoorapelta was the first of its kind named from the famous Morrison Formation of the American West.","image":"https://upload.wikimedia.org/wikipedia/commons/8/83/Mymoorapelta_maysi.png"},{"name":"Niobrarasaurus","rarity":"common","id":"niobrarasaurus","subtitle":"Armored","details":"A Late Cretaceous nodosaur from Kansas, Niobrarasaurus was found in chalk laid down by an inland sea that once covered the center of North America.","image":"https://images.dinosaurpictures.org/Niobrarasaurus/Niobrarasaurus_aaa22c9e.jpg"},{"name":"Scolosaurus","rarity":"common","id":"scolosaurus","subtitle":"Armored","details":"A Late Cretaceous ankylosaur from Alberta, Scolosaurus is known in unusual detail, with fossils preserving much of its distinctive pattern of body armor.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8b/Scolosaurus.png"},{"name":"Shamosaurus","rarity":"common","id":"shamosaurus","subtitle":"Armored","details":"An Early Cretaceous ankylosaur from Mongolia, Shamosaurus was an early member of its family with a relatively flat, broad skull and heavy body armor.","image":"https://images.dinosaurpictures.org/Shamosaurus/Shamosaurus_d2703ddd.jpg"},{"name":"Stegopelta","rarity":"common","id":"stegopelta","subtitle":"Armored","details":"A Late Cretaceous nodosaur from Wyoming, Stegopelta carried fused armor over its shoulders and hips, forming solid shields above its vulnerable joints.","image":"https://images.dinosaurpictures.org/Stegopelta/Stegopelta_b44538b7.jpg"},{"name":"Taohelong","rarity":"common","id":"taohelong","subtitle":"Armored","details":"An Early Cretaceous nodosaur from China, Taohelong was the first polacanthine nodosaur identified from Asia, with armor and spikes over its hips and back.","image":"https://images.dinosaurpictures.org/Taohelong/taohelong_by_cisiopurple_da63p2t-fullview_80c6.jpg"},{"name":"Tianchisaurus","rarity":"common","id":"tianchisaurus","subtitle":"Armored","details":"A Middle Jurassic ankylosaur from China, Tianchisaurus was an early armored dinosaur nicknamed the Jurassic Park dinosaur by the scientists who described it.","image":"https://images.dinosaurpictures.org/Tianchisaurus/Tianchisaurus_f04e4e23.jpg"},{"name":"Pachycephalosaurus","rarity":"legendary","id":"pachycephalosaurus","subtitle":"Other Dinosaur","details":"A Late Cretaceous dome-headed dinosaur from Montana and South Dakota, Pachycephalosaurus had a solid skull roof reaching about 25 centimeters thick.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a5/Pachycephalosaurus_TD.png"},{"name":"Plateosaurus","rarity":"legendary","id":"plateosaurus","subtitle":"Other Dinosaur","details":"A Late Triassic prosauropod from Germany and France, Plateosaurus was a bulky early sauropod relative known from hundreds of skeletons in mass burials.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e0/Plateosaurus_TD.png"},{"name":"Heterodontosaurus","rarity":"legendary","id":"heterodontosaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic ornithischian from South Africa, Heterodontosaurus was tiny and had three kinds of teeth in its jaws, including a pair of small tusks.","image":"https://upload.wikimedia.org/wikipedia/commons/6/64/Heterodontosaurus_TD.png"},{"name":"Stegoceras","rarity":"epic","id":"stegoceras","subtitle":"Other Dinosaur","details":"A Late Cretaceous dome-head from Alberta, Stegoceras was small, and its complete skulls anchor much of the study of pachycephalosaur anatomy and growth.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/Stegoceras_TD.png"},{"name":"Prenocephale","rarity":"epic","id":"prenocephale","subtitle":"Other Dinosaur","details":"A Late Cretaceous dome-headed dinosaur from Mongolia, Prenocephale had large eyes and a smooth, high skull dome ringed by small bony knobs at its base.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Prenocephale_TD.png"},{"name":"Dryosaurus","rarity":"epic","id":"dryosaurus","subtitle":"Other Dinosaur","details":"A Late Jurassic ornithopod from Wyoming and Tanzania, Dryosaurus was a fast, lightly built herbivore that ran on two legs across Morrison floodplains.","image":"https://upload.wikimedia.org/wikipedia/commons/5/58/Dryosaurus_TD.png"},{"name":"Hypsilophodon","rarity":"epic","id":"hypsilophodon","subtitle":"Other Dinosaur","details":"An Early Cretaceous herbivore from England, Hypsilophodon was a small two-legged runner once wrongly imagined as a tree-climber with grasping feet.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Hypsilophodon_TD.png"},{"name":"Tenontosaurus","rarity":"epic","id":"tenontosaurus","subtitle":"Other Dinosaur","details":"An Early Cretaceous ornithopod from Oklahoma and Montana, Tenontosaurus was mid-sized and is often found near remains of the predator Deinonychus.","image":"https://upload.wikimedia.org/wikipedia/commons/4/41/Tenontosaurus_TD.png"},{"name":"Massospondylus","rarity":"rare","id":"massospondylus","subtitle":"Other Dinosaur","details":"An Early Jurassic prosauropod from South Africa, Massospondylus is famous for fossil embryos that rank among the oldest known for any dinosaur species.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Massospondylus_TD.png"},{"name":"Gasparinisaura","rarity":"rare","id":"gasparinisaura","subtitle":"Other Dinosaur","details":"A Late Cretaceous ornithopod from Argentina, Gasparinisaura was a small, lightly built herbivore from Patagonia, known from skeletons including juveniles.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Gasparinisaura_BW.jpg"},{"name":"Thescelosaurus","rarity":"rare","id":"thescelosaurus","subtitle":"Other Dinosaur","details":"A Late Cretaceous ornithopod from Montana and South Dakota, Thescelosaurus was a sturdy small herbivore among the last dinosaurs before the asteroid impact.","image":"https://upload.wikimedia.org/wikipedia/commons/8/80/Thescelosaurus_neglectus.png"},{"name":"Camptosaurus","rarity":"rare","id":"camptosaurus","subtitle":"Other Dinosaur","details":"A Late Jurassic ornithopod from Wyoming, Camptosaurus was a beaked herbivore that walked on all fours but could rear up on two legs to feed higher up.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b6/Camptosaurus_TD.png"},{"name":"Adeopapposaurus","rarity":"rare","id":"adeopapposaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic prosauropod from Argentina, Adeopapposaurus was closely related to Massospondylus, with a long neck and a beaked snout for cropping plants.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bd/Adeopapposaurus_mognai.jpg"},{"name":"Homalocephale","rarity":"rare","id":"homalocephale","subtitle":"Other Dinosaur","details":"A Late Cretaceous pachycephalosaur from Mongolia, Homalocephale had a flat head, wide hips and ornamentation across the back of its broad, low skull.","image":"https://upload.wikimedia.org/wikipedia/commons/0/00/Homalocephale_body.jpg"},{"name":"Lufengosaurus","rarity":"rare","id":"lufengosaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic prosauropod from China, Lufengosaurus was a long-necked herbivore whose skeleton became the first dinosaur ever mounted in China.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8a/Lufengosaurus_sketch1.jpg"},{"name":"Riojasaurus","rarity":"rare","id":"riojasaurus","subtitle":"Other Dinosaur","details":"A Late Triassic prosauropod from Argentina, Riojasaurus was heavy-bodied and walked on all fours, too large to rear up on two legs like its relatives.","image":"https://dinosaurierwelt.com/wp-content/uploads/2019/06/riojasaurus.jpg"},{"name":"Anchisaurus","rarity":"uncommon","id":"anchisaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic prosauropod from Connecticut, Anchisaurus was slender and ranks among the first dinosaurs ever discovered in North America.","image":"https://upload.wikimedia.org/wikipedia/commons/0/08/Anchisaurus_NT.jpg"},{"name":"Melanorosaurus","rarity":"uncommon","id":"melanorosaurus","subtitle":"Other Dinosaur","details":"A Late Triassic sauropodomorph from South Africa, Melanorosaurus was a giant for its time and already walked on all fours like later true sauropods.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Melanorosaurus_readi_steveoc.jpg"},{"name":"Saturnalia","rarity":"uncommon","id":"saturnalia","subtitle":"Other Dinosaur","details":"A Late Triassic sauropodomorph from Brazil, Saturnalia was one of the earliest of its group, small and lightly built, with a long neck and small head.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/Saturnalia_tupiniquim.jpg"},{"name":"Eoraptor","rarity":"uncommon","id":"eoraptor","subtitle":"Other Dinosaur","details":"A Late Triassic dinosaur from Argentina, Eoraptor was small and early, living close to the split between the great lineages of the dinosaur family tree.","image":"https://upload.wikimedia.org/wikipedia/commons/3/37/Eoraptor_lunensis.png"},{"name":"Leaellynasaura","rarity":"uncommon","id":"leaellynasaura","subtitle":"Other Dinosaur","details":"An Early Cretaceous ornithopod from Australia, Leaellynasaura was a small polar herbivore that lived through months of darkness each polar winter.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4b/Leaellynasaura.jpg"},{"name":"Oryctodromeus","rarity":"uncommon","id":"oryctodromeus","subtitle":"Other Dinosaur","details":"A Mid-Cretaceous ornithopod from Montana, Oryctodromeus was a small burrowing herbivore found curled inside the remains of its own underground burrow.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Oryctodromeus_TD.png"},{"name":"Rhabdodon","rarity":"uncommon","id":"rhabdodon","subtitle":"Other Dinosaur","details":"A Late Cretaceous ornithopod from France, Rhabdodon was a robust herbivore that lived on the island archipelago that made up much of ancient Europe.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Rhabdodon.jpg"},{"name":"Zalmoxes","rarity":"uncommon","id":"zalmoxes","subtitle":"Other Dinosaur","details":"A Late Cretaceous ornithopod from Romania, Zalmoxes was a stocky dwarf herbivore that lived on the prehistoric island of Hateg in ancient Europe.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Zalmoxes_TD.png"},{"name":"Scelidosaurus","rarity":"uncommon","id":"scelidosaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic thyreophoran from England, Scelidosaurus was an early armored dinosaur with rows of bony studs, from before stegosaurs and ankylosaurs split.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Scelidosaurus_TD.png"},{"name":"Scutellosaurus","rarity":"uncommon","id":"scutellosaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic thyreophoran from Arizona, Scutellosaurus was a small, lightly armored two-legged dinosaur with a long tail and rows of tiny scutes.","image":"https://upload.wikimedia.org/wikipedia/commons/0/09/Scutellosaurus_TD.png"},{"name":"Acrotholus","rarity":"uncommon","id":"acrotholus","subtitle":"Other Dinosaur","details":"A Late Cretaceous dome-head from Alberta, Acrotholus ranks among the smallest North American pachycephalosaurs, known from its thick fossil skull caps.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/Acrotholus_NT.jpg"},{"name":"Goyocephale","rarity":"uncommon","id":"goyocephale","subtitle":"Other Dinosaur","details":"A Late Cretaceous pachycephalosaur from Mongolia, Goyocephale had a flat head with small horns at the back of its skull and a covering of bony studs.","image":"https://upload.wikimedia.org/wikipedia/commons/8/80/Goyocephale.jpg"},{"name":"Tylocephale","rarity":"uncommon","id":"tylocephale","subtitle":"Other Dinosaur","details":"A Late Cretaceous pachycephalosaur from Mongolia, Tylocephale had an unusually tall, narrow dome on its skull, one of the tallest in its family group.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5c/Tylocephale_pair.jpg"},{"name":"Yunnanosaurus","rarity":"uncommon","id":"yunnanosaurus","subtitle":"Other Dinosaur","details":"An Early Jurassic prosauropod from China, Yunnanosaurus was a long-necked herbivore with spoon-shaped teeth well suited to cropping leaves and plants.","image":"https://cdnb.artstation.com/p/assets/images/images/049/726/927/large/cheung-chung-tat-yunnanosaurus08.jpg?1653174311"},{"name":"Agilisaurus","rarity":"common","id":"agilisaurus","subtitle":"Other Dinosaur","details":"A tiny, lightly built two-legged herbivore from the Middle Jurassic of China, Agilisaurus was a quick, agile plant-eater among the early ornithischians.","image":"https://upload.wikimedia.org/wikipedia/commons/b/ba/Agilisaurus_life_restoration.jpg"},{"name":"Diluvicursor","rarity":"common","id":"diluvicursor","subtitle":"Other Dinosaur","details":"A small ornithopod from Early Cretaceous Victoria, Australia, Diluvicursor means 'flood runner' and is known from a partial skeleton with a long tail.","image":"https://upload.wikimedia.org/wikipedia/commons/9/92/Diluvicursor_life_restoration.png"},{"name":"Nanosaurus","rarity":"common","id":"nanosaurus","subtitle":"Other Dinosaur","details":"A small, quick ornithopod from the Late Jurassic of Colorado, Nanosaurus lived in the Morrison Formation alongside giants such as Stegosaurus and Allosaurus.","image":"https://images.dinosaurpictures.org/Nanosaurus/Nanosaurus_9015ab06.jpg"},{"name":"Parksosaurus","rarity":"common","id":"parksosaurus","subtitle":"Other Dinosaur","details":"A small thescelosaurid ornithopod from the Late Cretaceous of Alberta, Parksosaurus balanced and steered with a long tail as it ran on two slender legs.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ef/Parksosaurus_Steveoc86.jpg"},{"name":"Vectidromeus","rarity":"common","id":"vectidromeus","subtitle":"Other Dinosaur","details":"A small, fleet-footed ornithopod from the Early Cretaceous of the Isle of Wight, England, Vectidromeus is known from the skeleton of a young individual.","image":"https://upload.wikimedia.org/wikipedia/commons/3/33/Vectidromeus_TD.png"},{"name":"Atlascopcosaurus","rarity":"common","id":"atlascopcosaurus","subtitle":"Other Dinosaur","details":"A small ornithopod from Early Cretaceous Australia, Atlascopcosaurus is known from jaws and teeth recovered from the rich fossil beds at Dinosaur Cove.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8d/Atlas_wiki.jpg"},{"name":"Talenkauen","rarity":"common","id":"talenkauen","subtitle":"Other Dinosaur","details":"A Patagonian ornithopod from the Late Cretaceous of Argentina, Talenkauen carried thin bony plates along its ribs, a rare feature among its relatives.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Talenkauen_TD.png"},{"name":"Anabisetia","rarity":"common","id":"anabisetia","subtitle":"Other Dinosaur","details":"A small two-legged ornithopod from the Late Cretaceous of Argentina, Anabisetia was preserved in a Patagonian river deposit in the Neuquen region.","image":"https://images.dinosaurpictures.org/Anabisetia/Anabisetia_05a45b08.jpg"},{"name":"Mochlodon","rarity":"common","id":"mochlodon","subtitle":"Other Dinosaur","details":"A small rhabdodontid ornithopod from the Late Cretaceous of Austria and Hungary, Mochlodon lived on the scattered islands of the ancient European seas.","image":"https://images.dinosaurpictures.org/Mochlodon/Mochlodon_dalfmy6-f54c370e-1d10-444a-b67d-a409c6ccd482_d9d4.jpg"},{"name":"Alaskacephale","rarity":"common","id":"alaskacephale","subtitle":"Other Dinosaur","details":"A small dome-headed dinosaur from the Late Cretaceous of Alaska, Alaskacephale lived north of the Arctic Circle in a land of long polar winters.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Alaskacephale_gangloffi.png"},{"name":"Colepiocephale","rarity":"common","id":"colepiocephale","subtitle":"Other Dinosaur","details":"A dome-headed dinosaur from the Late Cretaceous of Alberta, Colepiocephale is recognised by a distinctive bump at the back of its thickened skull.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Colepiocephale_updating_version.JPG"},{"name":"Wannanosaurus","rarity":"common","id":"wannanosaurus","subtitle":"Other Dinosaur","details":"One of the smallest known pachycephalosaurs, from the Late Cretaceous of China, Wannanosaurus measured barely over half a metre from nose to tail.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a1/Wannanosaurus_for_wiki_review.jpg"},{"name":"Buriolestes","rarity":"common","id":"buriolestes","subtitle":"Other Dinosaur","details":"An early sauropodomorph from the Late Triassic of Brazil, Buriolestes still had the sharp, curved teeth of a meat-eater, unlike its giant plant-eating kin.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d1/Buriolestes_schultzi_restoration.png"},{"name":"Panphagia","rarity":"common","id":"panphagia","subtitle":"Other Dinosaur","details":"An early sauropodomorph from the Late Triassic of Argentina, Panphagia shows the shift toward plant-eating that led to the giant long-necked sauropods.","image":"https://upload.wikimedia.org/wikipedia/commons/7/74/Panphagia_NT.jpg"},{"name":"Sarahsaurus","rarity":"common","id":"sarahsaurus","subtitle":"Other Dinosaur","details":"An early sauropod relative from the Early Jurassic of Arizona, Sarahsaurus was a prosauropod with unusually powerful hands tipped with large claws.","image":"https://www.phoenixzoo.org/wp-content/uploads/2026/07/Sarahsaurus-credit-Brian-Engh-1-e1785356626803-1024x766.png"},{"name":"Jingshanosaurus","rarity":"common","id":"jingshanosaurus","subtitle":"Other Dinosaur","details":"A prosauropod from the Early Jurassic of China, Jingshanosaurus was close in form to Yunnanosaurus and walked on two legs or on all fours to feed.","image":"https://upload.wikimedia.org/wikipedia/commons/7/72/Jingshanosaurus_xinwaensis.png"},{"name":"Efraasia","rarity":"common","id":"efraasia","subtitle":"Other Dinosaur","details":"An early sauropodomorph from the Late Triassic of Germany, Efraasia is known from the classic Keuper fossil beds that preserve early dinosaur relatives.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7a/Efraasia.png"},{"name":"Emausaurus","rarity":"common","id":"emausaurus","subtitle":"Other Dinosaur","details":"An early armoured dinosaur from the Early Jurassic of Germany, Emausaurus is known from a single juvenile with the beginnings of thyreophoran armour.","image":"https://upload.wikimedia.org/wikipedia/commons/9/98/Emausaurus_TD.png"},{"name":"Lesothosaurus","rarity":"common","id":"lesothosaurus","subtitle":"Other Dinosaur","details":"A small, early ornithischian from the Early Jurassic of Lesotho, Lesothosaurus gives a glimpse of the beginnings of the great bird-hipped dinosaur group.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a1/Lesothosaurus_diagnosticus.png"},{"name":"Fruitadens","rarity":"common","id":"fruitadens","subtitle":"Other Dinosaur","details":"Among the smallest known ornithischian dinosaurs, Fruitadens from the Late Jurassic of Colorado measured no longer than a small cat from nose to tail.","image":"https://upload.wikimedia.org/wikipedia/commons/5/50/Fruitadens_transparent.png"},{"name":"Quetzalcoatlus","rarity":"legendary","id":"quetzalcoatlus","subtitle":"Flying & Marine Reptile","details":"A giant pterosaur from the Late Cretaceous of Texas, Quetzalcoatlus was among the largest flying animals known, with a wingspan often estimated near 10 metres.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e2/Quetzalcoatlus_northropi.png"},{"name":"Pteranodon","rarity":"legendary","id":"pteranodon","subtitle":"Flying & Marine Reptile","details":"A toothless fish-eating pterosaur from the Late Cretaceous seaway of North America, Pteranodon is known for its long, backward-pointing head crest.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Pteranodon_TD.png"},{"name":"Mosasaurus","rarity":"legendary","id":"mosasaurus","subtitle":"Flying & Marine Reptile","details":"A large paddle-limbed marine reptile from the Late Cretaceous, Mosasaurus was a mosasaur that hunted in seas over Europe and North America.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Mosasaurus.png"},{"name":"Pterodactylus","rarity":"epic","id":"pterodactylus","subtitle":"Flying & Marine Reptile","details":"A Late Jurassic pterosaur from Germany's Solnhofen limestone, Pterodactylus was one of the first pterosaurs described and lent its name to 'pterodactyl'.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Pterodactylus_holotype_fly_mmartyniuk_white_background.png"},{"name":"Tylosaurus","rarity":"epic","id":"tylosaurus","subtitle":"Flying & Marine Reptile","details":"One of the largest mosasaurs, from the Late Cretaceous of North America, Tylosaurus had a bony, reinforced snout tip and hunted fish, turtles and other mosasaurs.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bb/Tylosaurus_paleoart.jpg"},{"name":"Plesiosaurus","rarity":"epic","id":"plesiosaurus","subtitle":"Flying & Marine Reptile","details":"A small-headed, long-necked marine reptile from the Early Jurassic of England, Plesiosaurus swam with four large paddle-like flippers through ancient seas.","image":"https://upload.wikimedia.org/wikipedia/commons/6/65/Plesiosaurus_dolich1DB.jpg"},{"name":"Ichthyosaurus","rarity":"epic","id":"ichthyosaurus","subtitle":"Flying & Marine Reptile","details":"A dolphin-shaped marine reptile from the Early Jurassic of England, Ichthyosaurus gave birth to live young at sea rather than laying eggs on land.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Ichthyosaurus_anningae_trio_NT_small.jpg"},{"name":"Elasmosaurus","rarity":"rare","id":"elasmosaurus","subtitle":"Flying & Marine Reptile","details":"A Late Cretaceous plesiosaur from Kansas, Elasmosaurus was famous for an extremely long neck that made up about half of its entire body length.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Elasmosaurus_platyurus_%28transparent%29.png"},{"name":"Liopleurodon","rarity":"rare","id":"liopleurodon","subtitle":"Flying & Marine Reptile","details":"A short-necked pliosaur from Middle to Late Jurassic European seas, Liopleurodon was a marine reptile with large teeth and four powerful flippers.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ee/Liopleurodon_by_Cody_Lake.png"},{"name":"Kronosaurus","rarity":"rare","id":"kronosaurus","subtitle":"Flying & Marine Reptile","details":"One of the largest short-necked plesiosaurs known, Kronosaurus was an Early Cretaceous pliosaur from the inland seas of Australia and Colombia.","image":"https://upload.wikimedia.org/wikipedia/commons/2/24/Kronosaurus_queenslandicus_SW.png"},{"name":"Hatzegopteryx","rarity":"rare","id":"hatzegopteryx","subtitle":"Flying & Marine Reptile","details":"A giant azhdarchid pterosaur from the Late Cretaceous of Romania, Hatzegopteryx had an unusually stout skull and neck compared with other giant pterosaurs.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Hatzegopteryx_thambema.png"},{"name":"Dimorphodon","rarity":"rare","id":"dimorphodon","subtitle":"Flying & Marine Reptile","details":"An Early Jurassic pterosaur from England, Dimorphodon had two distinct types of teeth and a large, deep head that gave it a puffin-like profile.","image":"https://upload.wikimedia.org/wikipedia/commons/6/68/Dimorphodon-macronyx_jconway.jpg"},{"name":"Shonisaurus","rarity":"rare","id":"shonisaurus","subtitle":"Flying & Marine Reptile","details":"A Late Triassic ichthyosaur from Nevada, Shonisaurus was among the largest of its group, reaching lengths comparable to a modern sperm whale.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Life_restoration_of_Shonisaurus_popularis.png"},{"name":"Rhamphorhynchus","rarity":"uncommon","id":"rhamphorhynchus","subtitle":"Flying & Marine Reptile","details":"A long-tailed pterosaur from the Late Jurassic of Germany, Rhamphorhynchus had forward-pointing teeth well suited to snatching fish from the water.","image":"https://upload.wikimedia.org/wikipedia/commons/8/81/Rhamphorhynchus_muensteri_rendering.jpg"},{"name":"Tapejara","rarity":"uncommon","id":"tapejara","subtitle":"Flying & Marine Reptile","details":"An Early Cretaceous pterosaur from Brazil, Tapejara is known for its tall, elaborate head crest, which rose high above its short, deep beak.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1a/Tapejara_weln_DB2.jpg"},{"name":"Ophthalmosaurus","rarity":"uncommon","id":"ophthalmosaurus","subtitle":"Flying & Marine Reptile","details":"A Late Jurassic ichthyosaur from Europe and North America, Ophthalmosaurus had some of the largest eyes relative to body size of any vertebrate known.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Ophthalmosaurus_icenicus_updated_reconstruction.png"},{"name":"Cryptoclidus","rarity":"uncommon","id":"cryptoclidus","subtitle":"Flying & Marine Reptile","details":"A long-necked plesiosaur from the Middle Jurassic of England, Cryptoclidus is thought to have sifted soft prey from the water with its many small teeth.","image":"https://upload.wikimedia.org/wikipedia/commons/0/07/Cryptoclidus_eurymerus_SW.png"},{"name":"Pliosaurus","rarity":"uncommon","id":"pliosaurus","subtitle":"Flying & Marine Reptile","details":"A top marine predator from the Late Jurassic of Europe, Pliosaurus was a pliosaur with a huge skull armed with teeth the size of bananas.","image":"https://upload.wikimedia.org/wikipedia/commons/c/ca/Pliosaurus_irgisensisDB20.jpg"},{"name":"Archelon","rarity":"uncommon","id":"archelon","subtitle":"Flying & Marine Reptile","details":"The largest marine turtle known, Archelon was a Late Cretaceous sea turtle from North America with a leathery shell rather than a solid bony one.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Archelon1DB.jpg"},{"name":"Prognathodon","rarity":"uncommon","id":"prognathodon","subtitle":"Flying & Marine Reptile","details":"A robust mosasaur from the Late Cretaceous, found on several continents, Prognathodon had strong teeth suited to hard-shelled prey as well as fish.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d9/Prognathodon_saturator_DB.jpg"},{"name":"Pterodaustro","rarity":"uncommon","id":"pterodaustro","subtitle":"Flying & Marine Reptile","details":"An Early Cretaceous pterosaur from Argentina, Pterodaustro had hundreds of fine bristle-like teeth thought to have been used for filter-feeding.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e4/Pterodaustro_guinazui.png"},{"name":"Anhanguera","rarity":"common","id":"anhanguera","subtitle":"Flying & Marine Reptile","details":"A fish-eating pterosaur from the Early Cretaceous of Brazil, Anhanguera is recognised by the distinctive rounded crest on the front of its snout.","image":"https://upload.wikimedia.org/wikipedia/commons/4/41/Anhanguera_blittersdorffi_Life_Restoration_by_Matt_Martyniuk.png"},{"name":"Dsungaripterus","rarity":"common","id":"dsungaripterus","subtitle":"Flying & Marine Reptile","details":"An Early Cretaceous pterosaur from China, Dsungaripterus had an upturned jaw tip and knobbly teeth thought to have been used for crushing shellfish.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Dsungaripterus_weii.png"},{"name":"Anurognathus","rarity":"common","id":"anurognathus","subtitle":"Flying & Marine Reptile","details":"One of the smallest pterosaurs known, Anurognathus was a short-tailed Late Jurassic form from Germany likely hunting insects on the wing.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/AnurognathusDB_white_background.jpg"},{"name":"Platecarpus","rarity":"common","id":"platecarpus","subtitle":"Flying & Marine Reptile","details":"A mid-sized mosasaur from the Late Cretaceous of North America, Platecarpus is known from many well-preserved skeletons, including skin impressions.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c1/Platecarpus.jpg"},{"name":"Globidens","rarity":"common","id":"globidens","subtitle":"Flying & Marine Reptile","details":"A Late Cretaceous mosasaur found worldwide, Globidens was named for its rounded, globe-like teeth, which were well adapted for crushing shells.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/Globidens_paleoart.jpg"},{"name":"Temnodontosaurus","rarity":"common","id":"temnodontosaurus","subtitle":"Flying & Marine Reptile","details":"Among the largest ichthyosaurs of its time, Temnodontosaurus from the Early Jurassic of Europe had eyes among the biggest known in any animal.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Temnodontosaurus_DB.jpg"},{"name":"Mixosaurus","rarity":"common","id":"mixosaurus","subtitle":"Flying & Marine Reptile","details":"One of the earliest and smallest ichthyosaurs, Mixosaurus was a Middle Triassic marine reptile found on several continents around the ancient world.","image":"https://upload.wikimedia.org/wikipedia/commons/9/92/Mixosaurus_cornalianus_SW_1.png"},{"name":"Styxosaurus","rarity":"common","id":"styxosaurus","subtitle":"Flying & Marine Reptile","details":"A long-necked plesiosaur from the Late Cretaceous of North America, Styxosaurus is known to have swallowed stones, likely for ballast or digestion.","image":"https://upload.wikimedia.org/wikipedia/commons/7/71/Styxosaurus_BW.jpg"},{"name":"Nothosaurus","rarity":"common","id":"nothosaurus","subtitle":"Flying & Marine Reptile","details":"A semi-aquatic marine reptile from the Middle Triassic of Europe and Asia, Nothosaurus was a relative of the plesiosaurs, with webbed paddle-like limbs.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Nothosaurus_BW.jpg"},{"name":"Sue","rarity":"legendary","id":"sue","subtitle":"Famous Fossil","details":"Sue is a Tyrannosaurus rex found in South Dakota in 1990, among the largest and most complete T. rex skeletons known, displayed at Chicago's Field Museum.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/SUE-T-REX-FMNH-PR-2081-By-JJxFile.jpg"},{"name":"The Fighting Dinosaurs","rarity":"legendary","id":"the-fighting-dinosaurs","subtitle":"Famous Fossil","details":"The Fighting Dinosaurs are a Velociraptor and Protoceratops from Mongolia's Gobi Desert, preserved locked together and widely read as buried mid-struggle.","image":"https://upload.wikimedia.org/wikipedia/commons/2/23/Velociraptor_Fighting_Dinosaur.jpg"},{"name":"Dippy","rarity":"legendary","id":"dippy","subtitle":"Famous Fossil","details":"Dippy is a cast of a Diplodocus skeleton first displayed in Pittsburgh in 1907, whose copies in London and elsewhere introduced dinosaurs to worldwide audiences.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c0/%27Dippy%27_the_Diplodocus_%28geograph_6066103%29.jpg"},{"name":"Stan","rarity":"epic","id":"stan","subtitle":"Famous Fossil","details":"Stan is a Tyrannosaurus rex found in South Dakota in 1987, among the most complete T. rex skeletons known, long displayed in South Dakota before its 2020 sale.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Tyrannosaurus_Stan_National_Museum_of_Nature_and_Science.jpg"},{"name":"Scotty","rarity":"epic","id":"scotty","subtitle":"Famous Fossil","details":"Scotty is a Tyrannosaurus rex discovered in Saskatchewan, Canada in 1991, among the largest T. rex specimens known, displayed at the Royal Saskatchewan Museum.","image":"https://golden-west-content.s3.amazonaws.com/2025-08/Scotty%20the%20T.Rex%20in%20the%20CN%20gallery%20at%20the%20Royal%20Saskatchewan%20Museum%20in%20Regina%20%28photo%20by%20Gordon%20Edgar%29.jpg"},{"name":"Leonardo","rarity":"epic","id":"leonardo","subtitle":"Famous Fossil","details":"Leonardo is a mummified Brachylophosaurus found in Montana in 2000, a hadrosaur retaining fossilised skin and soft-tissue impressions over much of its body.","image":"https://upload.wikimedia.org/wikipedia/commons/d/da/Leonardo_dinosaur.jpg"},{"name":"The Berlin Archaeopteryx","rarity":"epic","id":"the-berlin-archaeopteryx","subtitle":"Famous Fossil","details":"The Berlin Archaeopteryx is a near-complete skeleton from Germany's Solnhofen limestone, found in the 1870s and a key fossil linking dinosaurs and birds.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9d/Archaeopteryx_lithographica_%28Berlin_specimen%29.jpg"},{"name":"Big Al","rarity":"rare","id":"big-al","subtitle":"Famous Fossil","details":"Big Al is a young Allosaurus found in Wyoming in 1991, unusually complete and scarred by numerous healed injuries and infections suffered during its life.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Big_Al_Allosaurus.jpg"},{"name":"Sophie","rarity":"rare","id":"sophie","subtitle":"Famous Fossil","details":"Sophie is a Stegosaurus found in Wyoming and displayed at London's Natural History Museum, among the most complete stegosaur skeletons known anywhere.","image":"https://upload.wikimedia.org/wikipedia/commons/9/90/Sophie_the_Stegosaurus_stenops_of_the_Natural_History_Museum%2C_London.jpg"},{"name":"The Dueling Dinosaurs","rarity":"rare","id":"the-dueling-dinosaurs","subtitle":"Famous Fossil","details":"The Dueling Dinosaurs are a Triceratops and a tyrannosaur from Montana's Hell Creek Formation, found in 2006; whether the pair actually fought is debated.","image":"https://upload.wikimedia.org/wikipedia/commons/3/34/Dueling_Dinosaurs_June_2024.jpg"},{"name":"Crystal Palace Dinosaurs","rarity":"rare","id":"crystal-palace-dinosaurs","subtitle":"Famous Fossil","details":"The Crystal Palace Dinosaurs are life-sized sculptures unveiled in London in 1854, the first of their kind and landmarks of early palaeontology in the park.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6e/Iguanadons_at_Crystal_Palace_%288063527051%29.jpg"},{"name":"Hell Creek Formation","rarity":"rare","id":"hell-creek-formation","subtitle":"Famous Fossil","details":"The Hell Creek Formation is a Late Cretaceous rock unit spanning Montana and the Dakotas, source of famous finds including Tyrannosaurus rex and Triceratops.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Upper_Cretaceous_Hell_Creek_Formation_%28GeoDIL_number_-_1118%29.jpg"},{"name":"Morrison Formation","rarity":"rare","id":"morrison-formation","subtitle":"Famous Fossil","details":"The Morrison Formation is a Late Jurassic rock unit across the American West, source of classic finds including Allosaurus, Stegosaurus and Diplodocus.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5c/Wall_of_Bones_in_the_Quarry_Building_at_Dinosaur_National_Monument_2012.JPG"},{"name":"Jane","rarity":"uncommon","id":"jane","subtitle":"Famous Fossil","details":"Jane is a small tyrannosaur found in Montana in 2001 and displayed in Illinois; whether it is a young T. rex or a separate genus, Nanotyrannus, is debated.","image":"https://upload.wikimedia.org/wikipedia/commons/4/44/Burpee_-_Jane_the_T-Rex_2.JPG"},{"name":"Flaming Cliffs","rarity":"uncommon","id":"flaming-cliffs","subtitle":"Famous Fossil","details":"The Flaming Cliffs are a fossil site in Mongolia's Gobi Desert, famed since 1920s expeditions for Protoceratops skeletons and early recognised dinosaur eggs.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b1/Bayanzag_%28Flaming_Cliffs%29.jpg"},{"name":"Solnhofen Limestone","rarity":"uncommon","id":"solnhofen-limestone","subtitle":"Famous Fossil","details":"The Solnhofen Limestone is a Late Jurassic deposit in Bavaria, Germany, famed for exquisitely detailed fossils including Archaeopteryx and many pterosaurs.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Steinbruch_Solnhofen_2004.jpg"},{"name":"Jehol Biota","rarity":"common","id":"jehol-biota","subtitle":"Famous Fossil","details":"The Jehol Biota are Early Cretaceous fossil beds in northeastern China, famed for feathered dinosaurs and early birds preserved in fine volcanic ash.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Microraptor_gui_%28BMNHC_Ph763%29_NMNS.jpg"},{"name":"Tendaguru Formation","rarity":"common","id":"tendaguru-formation","subtitle":"Famous Fossil","details":"The Tendaguru Formation is a Late Jurassic fossil site in Tanzania, source of major East African finds including Giraffatitan, Kentrosaurus and Dicraeosaurus.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/Giraffatitan_brancai_Naturkundemuseum_Berlin.jpg"},{"name":"Ghost Ranch","rarity":"common","id":"ghost-ranch","subtitle":"Famous Fossil","details":"Ghost Ranch is a fossil site in New Mexico famed for hundreds of Coelophysis skeletons found together in 1947, among the richest early-dinosaur bonebeds.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4e/Ghost_Ranch_redrock_cliffs.jpg"},{"name":"Dinosaur Provincial Park","rarity":"common","id":"dinosaur-provincial-park","subtitle":"Famous Fossil","details":"Dinosaur Provincial Park is a UNESCO World Heritage Site in Alberta, Canada, yielding dozens of Late Cretaceous dinosaur species from its badlands.","image":"https://upload.wikimedia.org/wikipedia/commons/4/48/Badlands_in_Dinosaur_Provincial_Park%2C_Alberta.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
